}

.rte-task-list p {
  margin: 0;
  padding: 0;
}

.rte-task-list label {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

.rte-task-list input[type="checkbox"] {
  cursor: pointer;
  appearance: none;
  width: 18px;
  height: 18px;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background-color: var(--background);
  vertical-align: middle;
  position: relative;
  flex-shrink: 0;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease,
    transform 0.1s ease;
}

.rte-task-list input[type="checkbox"]:active {
