}

.rte-task-list input[type="checkbox"]:checked {
  background-color: var(--primary);
  border-color: var(--primary);
}

/* Pop animation for the checkmark */
@keyframes checkmark-in {
  0% {
    transform: scale(0.5) rotate(-15deg);
    opacity: 0;
  }
  100% {
    transform: scale(1) rotate(0);
    opacity: 1;
  }
}

.rte-task-list input[type="checkbox"]:checked::before {
  position: absolute;
  content: "";
