import * as React from "react";
import { useState } from "react";
import { useEditorState } from "@tiptap/react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "../ui/popover";
import { Input } from "../ui/input";
import { Button } from "../ui/button";
import { Toggle } from "../ui/toggle";
import { useRichTextEditorContext } from "../rte-context";

export function LinkControl() {
  const { editor, labels, icons } = useRichTextEditorContext();
  const [url, setUrl] = useState("");
  const [open, setOpen] = useState(false);

  const active = useEditorState({
    editor: editor ?? null,
    selector: (ctx) =>
      ctx.editor && !ctx.editor.isDestroyed
        ? ctx.editor.isActive("link")
        : false,
  });

  const handleOpen = (isOpen: boolean) => {
    if (isOpen) {
      const linkData = editor?.getAttributes("link");
      setUrl(linkData?.href || "");
    } else {
      setUrl("");
    }
    setOpen(isOpen);
  };

  const handleSave = () => {
    if (!editor || editor.isDestroyed) return;
    if (url === "") {
      editor.chain().focus().extendMarkRange("link").unsetLink().run();
    } else {
      editor
        .chain()
        .focus()
        .extendMarkRange("link")
        .setLink({ href: url })
        .run();
    }
    setOpen(false);
    setUrl("");
  };

  const handleKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleSave();
    }
  };

  React.useEffect(() => {
    const handler = () => handleOpen(true);
    window.addEventListener("edit-link", handler);
    return () => window.removeEventListener("edit-link", handler);
  }, [editor]);

  return (
    <Popover open={open} onOpenChange={handleOpen}>
      <PopoverTrigger
        onMouseDown={(e: React.MouseEvent) => e.preventDefault()}
      >
        <Toggle
          size="sm"
          pressed={active ?? false}
          aria-label={labels.linkControlLabel}
          title={labels.linkControlLabel}
          className="p-0"
        >
          {icons.linkControlIcon}
        </Toggle>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-3">
        <div className="rte-link-editor">
          <Input
            type="url"
            placeholder={labels.linkEditorInputPlaceholder}
            aria-label={labels.linkEditorInputLabel}
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            onKeyDown={handleKeyDown}
            className="rte-link-editor-input h-8 text-sm"
          />
          <Button
            size="sm"
            variant="default"
            onClick={handleSave}
            className="rte-link-editor-save h-8"
          >
            {labels.linkEditorSave}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

import TipTapLink from '@tiptap/extension-link';

export const Link = TipTapLink.extend({
  addKeyboardShortcuts() {
    return {
      'Mod-k': () => {
        window.dispatchEvent(new Event('edit-link'));
        return true;
      },
    };
  },
}).configure({ openOnClick: false });

"use client";

import { useCallback, useRef, useEffect } from "react";
import { NodeViewWrapper, type NodeViewProps } from "@tiptap/react";

interface ResizableNodeViewProps extends NodeViewProps {
  children: React.ReactNode;
  lockAspect?: boolean;
  aspectRatio?: number;
  minWidth?: number;
  maxWidth?: number;
}

export function ResizableNodeView({
  node,
  selected,
  updateAttributes,
  view,
  children,
  lockAspect = false,
  aspectRatio = 16 / 9,
  minWidth = 300,
  maxWidth = 1200,
}: ResizableNodeViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const resizingRef = useRef<{
    direction: "right" | "bottom" | "corner";
    startX: number;
    startY: number;
    startWidth: number;
    startHeight: number;
    editorWidth: number;
  } | null>(null);

  const width = node.attrs.width as number | undefined;
  const height = node.attrs.height as number | undefined;
  const align = (node.attrs.align as string) || "center";

  const getEditorWidth = useCallback(() => {
    return view?.dom?.parentElement?.offsetWidth ?? 0;
  }, [view]);

  const handleMouseDown = useCallback(
    (e: React.MouseEvent, direction: "right" | "bottom" | "corner") => {
      e.preventDefault();
      e.stopPropagation();

      const editorWidth = getEditorWidth();
      const startWidth = containerRef.current?.offsetWidth ?? width ?? Math.min(560, editorWidth);
      const startHeight = containerRef.current?.offsetHeight ?? height ?? 315;

      resizingRef.current = {
        direction,
        startX: e.clientX,
        startY: e.clientY,
        startWidth,
        startHeight,
        editorWidth,
      };

      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", handleMouseUp);
      document.body.style.cursor =
        direction === "right"
          ? "ew-resize"
          : direction === "bottom"
            ? "ns-resize"
            : "nwse-resize";
      document.body.style.userSelect = "none";
    },
    [width, height, getEditorWidth],
  );

  const handleMouseMove = useCallback(
    (e: MouseEvent) => {
      const resize = resizingRef.current;
      if (!resize) return;

      const effectiveMax = Math.min(maxWidth, resize.editorWidth);

      let newWidth = resize.startWidth;
      let newHeight = resize.startHeight;

      if (resize.direction === "right" || resize.direction === "corner") {
        newWidth = Math.max(
          minWidth,
          Math.min(effectiveMax, resize.startWidth + (e.clientX - resize.startX)),
        );
      }

      if (resize.direction === "bottom" || resize.direction === "corner") {
        newHeight = Math.max(
          Math.round(minWidth / aspectRatio),
          Math.min(
            Math.round(effectiveMax / aspectRatio),
            resize.startHeight + (e.clientY - resize.startY),
          ),
        );
      }

      if (lockAspect) {
        if (resize.direction === "right" || resize.direction === "corner") {
          newHeight = Math.round(newWidth / aspectRatio);
        } else {
          newWidth = Math.round(newHeight * aspectRatio);
        }
      }

      if (containerRef.current) {
        containerRef.current.style.width = `${newWidth}px`;
        containerRef.current.style.height = `${newHeight}px`;
      }
    },
    [lockAspect, aspectRatio, minWidth, maxWidth],
  );

  const handleMouseUp = useCallback(() => {
    const resize = resizingRef.current;
    if (!resize) return;

    document.removeEventListener("mousemove", handleMouseMove);
    document.removeEventListener("mouseup", handleMouseUp);
    document.body.style.cursor = "";
    document.body.style.userSelect = "";

    if (containerRef.current) {
      const w = containerRef.current.offsetWidth;
      const h = containerRef.current.offsetHeight;
      updateAttributes({ width: w, height: h });
    }

    resizingRef.current = null;
  }, [handleMouseMove, updateAttributes]);

  useEffect(() => {
    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
    };
  }, [handleMouseMove]);

  return (
    <NodeViewWrapper
      className="rte-embed-wrapper"
      data-selected={selected || undefined}
      data-align={align}
    >
      <div
        ref={containerRef}
        className="rte-embed"
        contentEditable={false}
        style={{
          width: width ? `${width}px` : "100%",
          height: height ? `${height}px` : "auto",
          minWidth: `${minWidth}px`,
        }}
      >
        {children}
        {selected && (
          <>
            <div
              className="rte-resize-handle rte-resize-handle--right"
              onMouseDown={(e) => handleMouseDown(e, "right")}
            />
            <div
              className="rte-resize-handle rte-resize-handle--bottom"
              onMouseDown={(e) => handleMouseDown(e, "bottom")}
            />
            <div
              className="rte-resize-handle rte-resize-handle--corner"
              onMouseDown={(e) => handleMouseDown(e, "corner")}
            />
          </>
        )}
      </div>
    </NodeViewWrapper>
  );
}

"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import { Node, nodeInputRule } from "@tiptap/core";
import {
  ReactNodeViewRenderer,
  useEditorState,
  type NodeViewProps,
} from "@tiptap/react";
import { useRichTextEditorContext } from "../rte-context";
import { RichTextEditorControl } from "../controls/rte-control";
import { Input } from "../ui/input";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../ui/dialog";
import { ResizableNodeView } from "../extensions/resizable-node-view";

const WIDGET_SCRIPT_URL = "https://platform.twitter.com/widgets.js";

function TwitterNodeView(props: NodeViewProps) {
  const { node } = props;
  const containerRef = useRef<HTMLDivElement>(null);
  const [loading, setLoading] = useState(true);
  const tweetId = node.attrs.tweetId;
  const w = node.attrs.width as number | undefined;
  const h = node.attrs.height as number | undefined;

  const renderTweet = useCallback(() => {
    if (!containerRef.current || !tweetId) return;
    containerRef.current.innerHTML = "";
    setLoading(true);
    const twttr = (window as any).twttr;
    if (twttr?.widgets) {
      twttr.widgets.createTweet(tweetId, containerRef.current).then(() => {
        setLoading(false);
      });
    }
  }, [tweetId]);

  useEffect(() => {
    if (!containerRef.current || !tweetId) return;

    if ((window as any).twttr?.widgets) {
      renderTweet();
    } else {
      const script = document.createElement("script");
      script.src = WIDGET_SCRIPT_URL;
      script.async = true;
      script.onload = renderTweet;
      document.body.appendChild(script);
    }
  }, [tweetId, w, h, renderTweet]);

  return (
    <ResizableNodeView {...props} lockAspect={false} minWidth={300} maxWidth={1200}>
      {loading && <div className="rte-embed-loading">Loading tweet...</div>}
      <div ref={containerRef} />
    </ResizableNodeView>
  );
}

export const TwitterEmbed = Node.create({
  name: "twitter",
  group: "block",
  atom: true,
  draggable: true,

  addAttributes() {
    return {
      tweetId: {
        default: null,
        parseHTML: (el: HTMLElement) => el.getAttribute("data-tweet-id"),
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-tweet-id": attrs.tweetId,
        }),
      },
      width: {
        default: 550,
        parseHTML: (el: HTMLElement) =>
          el.getAttribute("data-width") ? Number(el.getAttribute("data-width")) : 550,
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-width": attrs.width,
        }),
      },
      height: {
        default: 400,
        parseHTML: (el: HTMLElement) =>
          el.getAttribute("data-height") ? Number(el.getAttribute("data-height")) : 400,
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-height": attrs.height,
        }),
      },
      align: {
        default: "center",
        parseHTML: (el: HTMLElement) =>
          el.getAttribute("data-align") || "center",
        renderHTML: (attrs: Record<string, unknown>) => ({
          "data-align": attrs.align,
        }),
      },
    };
  },

  parseHTML() {
    return [{ tag: 'div[data-type="twitter"]' }];
  },

  renderHTML({ node }: { node: { attrs: Record<string, unknown> } }) {
    return [
      "div",
      {
        "data-type": "twitter",
        "data-tweet-id": node.attrs.tweetId,
        "data-width": node.attrs.width,
        "data-height": node.attrs.height,
        "data-align": node.attrs.align,
      },
    ];
  },

  addNodeView() {
    return ReactNodeViewRenderer(TwitterNodeView) as any;
  },

  addCommands() {
    return {
      setTwitterEmbed:
        (tweetId: string) =>
        ({ commands }: { commands: any }) => {
          return commands.insertContent({
            type: "twitter",
            attrs: { tweetId },
          });
        },
    } as any;
  },

  addInputRules() {
    return [
      nodeInputRule({
        find: /https?:\/\/(?:www\.)?(?:twitter\.com|x\.com)\/\w+\/status\/(\d+)/,
        type: this.type,
        getAttributes: (match: RegExpMatchArray) => ({ tweetId: match[1] }),
      }),
    ];
  },
});

function extractTweetId(input: string): string | null {
  const clean = input.trim();
  const match = clean.match(/(?:twitter\.com|x\.com)\/(?:\w+\/status\/|i\/web\/status\/)(\d+)/);
  return match ? (match[1] ?? null) : /^\d+$/.test(clean) ? clean : null;
}

export function TwitterEmbedControl({ className }: { className?: string }) {
  const { editor } = useRichTextEditorContext();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");

  const { active } = useEditorState({
    editor: editor ?? null,
    selector: (ctx) => ({
      active:
        ctx.editor && !ctx.editor.isDestroyed
          ? ctx.editor.isActive("twitter")
          : false,
    }),
  }) ?? { active: false };

  const handleInsert = useCallback(() => {
    if (url && editor) {
      const tweetId = extractTweetId(url);
      if (tweetId) {
        (editor as any).chain().focus().setTwitterEmbed(tweetId).run();
        setUrl("");
      }
    }
  }, [url, editor]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger
        render={
          <RichTextEditorControl
            active={active}
            className={className}
            title="Embed Tweet"
            aria-label="Embed Tweet"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="currentColor"
              className="rte-editor-icon"
            >
              <path d="M18.2 3.2h3.3l-7.2 8.2 8.5 11.2h-6.6l-5.2-6.8-6 6.8H2.7l7.7-8.8L2.3 3.2h6.8l4.7 6.2 5.4-6.2zm-1.2 17.3h1.8L7 4.8H5.1l11.9 15.7z" />
            </svg>
          </RichTextEditorControl>
        }
      />
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Embed Tweet</DialogTitle>
          <DialogDescription>Paste a tweet URL or ID.</DialogDescription>
        </DialogHeader>
        <Input
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="https://x.com/user/status/..."
          onKeyDown={(e) => {
            if (e.key === "Enter" && url) {
              handleInsert();
              setOpen(false);
            }
          }}
        />
        <DialogFooter>
          <DialogClose>Cancel</DialogClose>
          <DialogClose
            disabled={!url}
            className="rounded-md bg-primary px-3 py-1.5 text-sm text-primary-foreground transition-opacity hover:opacity-90 disabled:opacity-50"
            onClick={handleInsert}
          >
            Insert
          </DialogClose>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

